WITH parsed AS (SELECT id, service, host, log_ts, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, COALESCE(context['version'], 'none') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['trace'] AS trace, COALESCE(context['region'], 'unknown') AS region_or_default FROM app_logs) SELECT host, DATE_TRUNC('DAY', log_ts) AS activity_day, service, COUNT(DISTINCT region_or_default) AS distinct_region_or_defaults, COUNT(CASE WHEN host = 'h3' THEN 1 END) AS h3_count, SORT_ARRAY(COLLECT_SET(host)) AS host_list, MAX(log_ts) AS last_seen, GROUPING_ID() AS gid FROM parsed GROUP BY GROUPING SETS ((host, DATE_TRUNC('DAY', log_ts), service), (host, DATE_TRUNC('DAY', log_ts)), (host), ()) HAVING distinct_region_or_defaults > 1;
